    const cs = getComputedStyle(b);
    return `${b.textContent.slice(0, 12)} pressed=${b.getAttribute('aria-pressed')} data=${b.hasAttribute('data-pressed')} hover=${b.matches(':hover')} focus=${b.matches(':focus')} bg=${cs.backgroundColor}`;
  }));
  console.log(vp.width, '\n' + state.join('\n'));
}
await browser.close();
EOF
